def _F(phi,k):
    n=400
    if phi==0:
        return 0.0
    a=0.0
    b=phi
    h=(b-a)/n
    s=0.0
    for i in range(n+1):
        x=a+i*h
        fx=1.0/math.sqrt(max(1e-15,1.0-k*k*(math.sin(x)**2)))
        c=4 if i%2==1 else 2
