    return s*h/3.0

def _sn(u,k):
    # invert F(phi,k)=u by bisection on phi in [-pi/2, pi/2]
    periodK=_K(k)
    m=2*periodK
    # fold into principal range using odd symmetry
    q=((u+periodK)%(2*m))-periodK
    sign=1.0
    if q<0:
        sign=-1.0
        q=-q
    lo=0.0
    hi=math.pi/2
    for _ in range(60):
        mid=(lo+hi)/2.0
        val=_F(mid,k)
        if val<q:
            lo=mid
        else:
            hi=mid
    phi=(lo+hi)/2.0
    return sign*math.sin(phi)

